using System;
using System.IO;
using System.Collections.Generic;
using System.Diagnostics;
using System.Reflection;
using System.Runtime.InteropServices;
public static class InstallationLocator {
 public static string RecordFile {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"FantasyStory","installations.txt");}}
 public static void Remember(string folder){try{var dirs=new HashSet<string>(StringComparer.OrdinalIgnoreCase);dirs.Add(Path.GetFullPath(folder));if(File.Exists(RecordFile))foreach(var old in File.ReadAllLines(RecordFile))if(dirs.Count<20&&Directory.Exists(old))dirs.Add(old);Directory.CreateDirectory(Path.GetDirectoryName(RecordFile));File.WriteAllLines(RecordFile,new List<string>(dirs).ToArray());}catch{}}
 public static string Resolve(string selected){if(String.IsNullOrWhiteSpace(selected))throw new Exception("게임 파일이나 폴더를 선택해 주세요.");var p=Path.GetFullPath(selected);if(File.Exists(p))p=Path.GetDirectoryName(p);var direct=PatchCore.InspectionError(p);if(direct==null)return p;if(String.Equals(Path.GetFileName(p),"resources",StringComparison.OrdinalIgnoreCase)){var parent=Directory.GetParent(p);if(parent!=null&&PatchCore.InspectionError(parent.FullName)==null)return parent.FullName;}
 var found=Find(new string[]{p},3,1500);if(found.Count==1)return found[0];if(found.Count>1)throw new Exception("선택한 폴더 아래에 게임이 여러 개 있습니다. 업데이트할 FantasyStory.exe를 직접 선택해 주세요.");throw new Exception(direct+"\n선택한 위치: "+p+"\nFantasyStory.exe가 있는 실제 게임 폴더를 선택해 주세요. ZIP 안의 파일은 먼저 압축을 해제해야 합니다.");}
 public static List<string> Find(IEnumerable<string> roots,int depth,int budget){var found=new List<string>();var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var queue=new Queue<Tuple<string,int>>();foreach(var root in roots)if(!String.IsNullOrWhiteSpace(root))queue.Enqueue(Tuple.Create(root,0));int count=0;while(queue.Count>0&&count++<budget){var item=queue.Dequeue();string p;try{p=Path.GetFullPath(item.Item1);if(!seen.Add(p)||!Directory.Exists(p)||(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)continue;if(PatchCore.InspectionError(p)==null){found.Add(p);continue;}if(item.Item2<depth)foreach(var child in Directory.GetDirectories(p))queue.Enqueue(Tuple.Create(child,item.Item2+1));}catch(UnauthorizedAccessException){}catch(IOException){}catch(System.Security.SecurityException){}catch(ArgumentException){}}return found;}
 public static List<string> Discover(string patchFolder){var roots=new List<string>();if(File.Exists(RecordFile))try{roots.AddRange(File.ReadAllLines(RecordFile));}catch{}foreach(var process in Process.GetProcessesByName("FantasyStory")){try{roots.Add(Path.GetDirectoryName(process.MainModule.FileName));}catch{}finally{process.Dispose();}}
 roots.Add(patchFolder);var parent=Directory.GetParent(patchFolder);if(parent!=null)roots.Add(parent.FullName);
 roots.Add(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory));roots.Add(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments));var profile=Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);roots.Add(Path.Combine(profile,"Downloads"));try{using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders")){var value=key==null?null:key.GetValue("{374DE290-123F-4565-9164-39C4925E467B}") as string;if(value!=null)roots.Add(Environment.ExpandEnvironmentVariables(value));}}catch{}
 roots.Add(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","FantasyStory"));
 foreach(var shortcutRoot in new string[]{Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),Environment.GetFolderPath(Environment.SpecialFolder.StartMenu)}){foreach(var target in ShortcutTargets(shortcutRoot))roots.Insert(0,target);}
 foreach(var drive in DriveInfo.GetDrives())try{if(drive.IsReady&&drive.DriveType==DriveType.Fixed){foreach(var name in new string[]{"Games","Game","게임","FantasyStory","이세계 기록","Program Files","Program Files (x86)"})roots.Add(Path.Combine(drive.RootDirectory.FullName,name));}}catch{}
 return Find(roots,5,6000);
 }
 static IEnumerable<string> ShortcutTargets(string root){var result=new List<string>();object shell=null;try{var type=Type.GetTypeFromProgID("WScript.Shell");if(type==null||!Directory.Exists(root))return result;shell=Activator.CreateInstance(type);var files=new List<string>(Directory.GetFiles(root,"*.lnk"));var programs=Path.Combine(root,"Programs");if(Directory.Exists(programs))files.AddRange(Directory.GetFiles(programs,"*Fantasy*.lnk",SearchOption.TopDirectoryOnly));foreach(var file in files){object shortcut=null;try{shortcut=type.InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{file});var target=(string)shortcut.GetType().InvokeMember("TargetPath",BindingFlags.GetProperty,null,shortcut,null);if(String.Equals(Path.GetFileName(target),"FantasyStory.exe",StringComparison.OrdinalIgnoreCase))result.Add(Path.GetDirectoryName(target));}catch{}finally{if(shortcut!=null&&Marshal.IsComObject(shortcut))Marshal.ReleaseComObject(shortcut);}}}catch{}finally{if(shell!=null&&Marshal.IsComObject(shell))Marshal.ReleaseComObject(shell);}return result;}
 public static bool Running(string folder){var exe=Path.Combine(folder,"FantasyStory.exe");foreach(var process in Process.GetProcessesByName("FantasyStory")){try{if(String.Equals(process.MainModule.FileName,exe,StringComparison.OrdinalIgnoreCase))return true;}catch(System.ComponentModel.Win32Exception){throw new Exception("게임 실행 여부를 확인할 수 없습니다. 게임을 종료하고 다시 시도해 주세요.");}catch(InvalidOperationException){}finally{process.Dispose();}}return false;}
}
